use clap::{Parser, Subcommand};
use std::path::PathBuf;
use anyhow::Result;

mod commands;
mod config;
mod parser;
mod graph;
mod utils;

use commands::*;

#[derive(Parser)]
#[command(name = "dep-tree")]
#[command(about = "Visualize your dependencies graphically", long_about = None)]
#[command(version = "v0.23.4")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

    /// path to dep-tree's config file.
    #[arg(short, long, global = true, default_value = ".dep-tree.yml")]
    config: PathBuf,

    /// Files that do not match this glob pattern will be ignored. You can provide an arbitrary number of --only flags.
    #[arg(long = "only", global = true)]
    only: Vec<String>,

    /// Files that match this glob pattern will be ignored. You can provide an arbitrary number of --exclude flags.
    #[arg(long = "exclude", global = true)]
    exclude: Vec<String>,

    /// trace re-exported symbols to the file where they are declared.
    #[arg(long, global = true, default_value = "false")]
    unwrap_exports: bool,

    /// follow the tsconfig.json paths while resolving imports.
    #[arg(long = "js-tsconfig-paths", global = true, default_value = "true")]
    js_tsconfig_paths: bool,

    /// take the workspaces attribute in the root package.json into account for resolving paths.
    #[arg(long = "js-workspaces", global = true, default_value = "true")]
    js_workspaces: bool,

    /// exclude imports wrapped inside if or try statements.
    #[arg(long = "python-exclude-conditional-imports", global = true, default_value = "false")]
    python_exclude_conditional_imports: bool,

    /// Entrypoints (for default command, positional args)
    #[arg(trailing_var_arg = true, allow_hyphen_values = true)]
    entrypoints: Vec<String>,
}

#[derive(Subcommand)]
enum Commands {
    /// (default) Renders a 3d force-directed graph in the browser
    Entropy(EntropyCmd),
    /// Render the dependency tree starting from the provided entrypoint
    Tree(TreeCmd),
    /// Checks that the dependency rules defined in the configuration file are not broken
    Check(CheckCmd),
    /// Shows all the dependencies between two parts of the code
    Explain(ExplainCmd),
    /// Generates a sample config in case that there's not already one present
    #[command(alias = "init")]
    Config(ConfigCmd),
    /// Help about any command
    Help,
}

#[tokio::main]
async fn main() -> Result<()> {
    let mut args = std::env::args().collect::<Vec<_>>();

    // If no arguments provided, show help
    if args.len() < 2 {
        println!("{}", include_str!("help.txt"));
        return Ok(());
    }

    // Check if first arg is a help-like command
    match args.get(1).map(|s| s.as_str()) {
        Some("--help") | Some("-h") | Some("help") => {
            println!("{}", include_str!("help.txt"));
            return Ok(());
        }
        Some("--version") | Some("-v") => {
            println!("dep-tree version v0.23.4");
            return Ok(());
        }
        _ => {}
    }

    // If first arg is a path (file/pattern), treat it as entropy command
    let first_arg = args.get(1).map(|s| s.as_str());
    let is_command = matches!(first_arg, 
        Some("entropy") | Some("tree") | Some("check") | Some("explain") | Some("config") | Some("help")
    );

    if !is_command && first_arg.is_some() {
        // Default command is entropy with the first arg as entrypoint
        args.insert(1, "entropy".to_string());
    }

    let cli = Cli::parse();

    match cli.command {
        Some(Commands::Entropy(cmd)) => cmd.run(cli).await?,
        Some(Commands::Tree(cmd)) => cmd.run(cli).await?,
        Some(Commands::Check(cmd)) => cmd.run(cli).await?,
        Some(Commands::Explain(cmd)) => cmd.run(cli).await?,
        Some(Commands::Config(cmd)) => cmd.run(cli).await?,
        Some(Commands::Help) | None => {
            println!("{}", include_str!("help.txt"));
        }
    }

    Ok(())
}
EOF

