    /// When there's an overlap between the files at the left and the right, keep the ones at the left
    #[arg(short = 'l', long)]
    overlap_left: bool,

    /// When there's an overlap between the files at the left and the right, keep the ones at the right
    #[arg(short = 'r', long)]
    overlap_right: bool,
