use regex::Regex;
use std::path::PathBuf;
use lazy_static::lazy_static;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Import {
    pub source: String,
    pub resolved_path: Option<PathBuf>,
    pub line: usize,
}

pub struct ImportParser;

impl ImportParser {
    pub fn parse_python(content: &str) -> Vec<Import> {
        let mut imports = Vec::new();

        lazy_static! {
            static ref FROM_IMPORT: Regex = Regex::new(r"^\s*from\s+([a-zA-Z0-9_.]+)\s+import").unwrap();
            static ref IMPORT: Regex = Regex::new(r"^\s*import\s+([a-zA-Z0-9_.,\s]+)").unwrap();
        }

        for (line_num, line) in content.lines().enumerate() {
            // Skip comments
            let line = line.split('#').next().unwrap_or("");

            if let Some(caps) = FROM_IMPORT.captures(line) {
                let source = caps.get(1).unwrap().as_str().to_string();
                if !source.starts_with('.') && source != "." {
                    // Skip absolute imports for now
                    continue;
                }
                imports.push(Import {
                    source,
                    resolved_path: None,
                    line: line_num + 1,
                });
            } else if let Some(caps) = IMPORT.captures(line) {
                let source = caps.get(1).unwrap().as_str().to_string();
                if !source.starts_with('.') {
                    // Skip absolute imports for now
                    continue;
                }
                for module in source.split(',') {
                    let module = module.trim();
                    if module.starts_with('.') {
                        imports.push(Import {
                            source: module.to_string(),
                            resolved_path: None,
                            line: line_num + 1,
                        });
                    }
                }
            }
        }

        imports
    }

    pub fn parse_javascript(content: &str) -> Vec<Import> {
        let mut imports = Vec::new();

        lazy_static! {
            static ref IMPORT_FROM: Regex =
                Regex::new(r#"^\s*import\s+(?:[\w\s{},*]*\s+)?from\s+['"]([^'"]+)['"]\s*;?"#)
                    .unwrap();
            static ref REQUIRE: Regex = Regex::new(r#"require\(['"]([^'"]+)['"]\)"#).unwrap();
            static ref EXPORT_FROM: Regex =
                Regex::new(r#"^\s*export\s+(?:[\w\s{},*]*\s+)?from\s+['"]([^'"]+)['"]\s*;?"#)
                    .unwrap();
        }

        for (line_num, line) in content.lines().enumerate() {
            // Skip comments
            let line = if let Some(idx) = line.find("//") {
                &line[..idx]
            } else {
                line
            };

            if let Some(caps) = IMPORT_FROM.captures(line) {
                let source = caps.get(1).unwrap().as_str().to_string();
                imports.push(Import {
                    source,
                    resolved_path: None,
                    line: line_num + 1,
                });
            } else if let Some(caps) = EXPORT_FROM.captures(line) {
                let source = caps.get(1).unwrap().as_str().to_string();
                imports.push(Import {
                    source,
                    resolved_path: None,
                    line: line_num + 1,
                });
            } else if let Some(caps) = REQUIRE.captures(line) {
                let source = caps.get(1).unwrap().as_str().to_string();
                imports.push(Import {
                    source,
                    resolved_path: None,
                    line: line_num + 1,
                });
            }
        }

        imports
    }

    pub fn parse_rust(content: &str) -> Vec<Import> {
        let mut imports = Vec::new();

        lazy_static! {
            static ref USE: Regex = Regex::new(r"^\s*use\s+([a-zA-Z0-9_:{}*,\s]+)").unwrap();
        }

        for (line_num, line) in content.lines().enumerate() {
            if let Some(caps) = USE.captures(line) {
                let source = caps.get(1).unwrap().as_str().trim().to_string();
                imports.push(Import {
                    source,
                    resolved_path: None,
                    line: line_num + 1,
                });
            }
        }

        imports
    }

    pub fn parse_go(content: &str) -> Vec<Import> {
        let mut imports = Vec::new();

        lazy_static! {
            static ref IMPORT: Regex = Regex::new(r#"\bimport\s+(?:"([^"]+)"|(?:\())"#).unwrap();
            static ref QUOTED: Regex = Regex::new(r#""([^"]+)""#).unwrap();
        }

        let content_for_quotes = content.clone();

        for (line_num, line) in content.lines().enumerate() {
            if let Some(caps) = IMPORT.captures(line) {
                if let Some(path) = caps.get(1) {
                    let source = path.as_str().to_string();
                    imports.push(Import {
                        source,
                        resolved_path: None,
                        line: line_num + 1,
                    });
                }
            }
        }

        // For multi-line imports, find all quoted strings
        for caps in QUOTED.captures_iter(&content_for_quotes) {
            let source = caps.get(1).unwrap().as_str().to_string();
            if !source.is_empty() {
                imports.push(Import {
                    source,
                    resolved_path: None,
                    line: 0,
                });
            }
        }

        imports
    }
}
