use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use serde_json::{json, Value};

#[derive(Debug, Clone)]
pub struct Node {
    pub path: PathBuf,
    pub dependencies: HashSet<PathBuf>,
}

pub struct DependencyGraph {
    pub nodes: HashMap<PathBuf, Node>,
}

impl DependencyGraph {
    pub fn new() -> Self {
        DependencyGraph {
            nodes: HashMap::new(),
        }
    }

    pub fn add_node(&mut self, path: PathBuf) {
        if !self.nodes.contains_key(&path) {
            self.nodes.insert(path.clone(), Node {
                path,
                dependencies: HashSet::new(),
            });
        }
    }

    pub fn add_dependency(&mut self, from: PathBuf, to: PathBuf) {
        self.add_node(from.clone());
        self.add_node(to.clone());
        if let Some(node) = self.nodes.get_mut(&from) {
            node.dependencies.insert(to);
        }
    }

    pub fn to_json(&self, root: &PathBuf) -> Value {
        let mut visited = HashSet::new();
        let tree = self.build_tree(root, &mut visited);
        json!({
            "tree": tree,
            "circularDependencies": [],
            "errors": {}
        })
    }

    fn build_tree(&self, node: &PathBuf, visited: &mut HashSet<PathBuf>) -> Value {
        if visited.contains(node) {
            return Value::Null;
        }

        visited.insert(node.clone());

        if let Some(file_node) = self.nodes.get(node) {
            let mut children = serde_json::Map::new();
            for dep in &file_node.dependencies {
                children.insert(
                    dep.to_string_lossy().to_string(),
                    self.build_tree(dep, visited),
                );
            }
            Value::Object(children)
        } else {
            Value::Null
        }
    }
}
