use glob::glob;
use std::path::{Path, PathBuf};
use walkdir::WalkDir;
use regex::Regex;

pub fn get_matching_files(
    patterns: &[String],
    exclude_patterns: &[String],
    only_patterns: &[String],
) -> Vec<PathBuf> {
    let mut files = Vec::new();

    // Collect all files matching the patterns
    for pattern in patterns {
        for entry in glob(pattern).unwrap_or_else(|_| {
            glob("").unwrap_or_else(|_| glob("**").unwrap_or_else(|_| glob(".").unwrap()))
        }) {
            if let Ok(path) = entry {
                if path.is_file() {
                    files.push(path);
                }
            }
        }
    }

    // Filter out excluded patterns
    if !exclude_patterns.is_empty() {
        files.retain(|file| {
            !exclude_patterns.iter().any(|pattern| {
                glob_matches(file, pattern)
            })
        });
    }

    // Filter by only patterns
    if !only_patterns.is_empty() {
        files.retain(|file| {
            only_patterns.iter().any(|pattern| {
                glob_matches(file, pattern)
            })
        });
    }

    files.sort();
    files.dedup();
    files
}

pub fn glob_matches(path: &Path, pattern: &str) -> bool {
    let pattern_str = pattern
        .replace("**", ".*")
        .replace("*", "[^/]*")
        .replace("?", "[^/]");
    let pattern_str = format!("^{}$", pattern_str);
    if let Ok(re) = Regex::new(&pattern_str) {
        re.is_match(&path.to_string_lossy())
    } else {
        false
    }
}

pub fn find_files_recursively(root: &Path, extensions: &[&str]) -> Vec<PathBuf> {
    let mut files = Vec::new();
    for entry in WalkDir::new(root)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().is_file())
    {
        let path = entry.path();
        if let Some(ext) = path.extension() {
            if extensions.contains(&ext.to_string_lossy().as_ref()) {
                files.push(path.to_path_buf());
            }
        }
    }
    files
}

pub fn resolve_path(base: &Path, import_path: &str) -> Option<PathBuf> {
    let mut candidates = Vec::new();

    // Handle relative imports
    if import_path.starts_with('.') {
        let base_dir = if base.is_file() {
            base.parent()
        } else {
            Some(base)
        };

        if let Some(dir) = base_dir {
            // Direct path with extension
            candidates.push(dir.join(format!("{}.py", import_path)));
            candidates.push(dir.join(format!("{}.js", import_path)));
            candidates.push(dir.join(format!("{}.ts", import_path)));
            candidates.push(dir.join(format!("{}.go", import_path)));
            candidates.push(dir.join(format!("{}.rs", import_path)));

            // As package/module
            candidates.push(dir.join(import_path).join("__init__.py"));
            candidates.push(dir.join(import_path).join("index.js"));
            candidates.push(dir.join(import_path).join("index.ts"));
        }
    }

    for candidate in candidates {
        if candidate.exists() {
            return Some(candidate);
        }
    }

    None
}
