            python_exclude_conditional_imports: false,
            json: false,
            enable_gui: false,
            no_browser_open: false,
            render_path: None,
            overlap_left: false,
            overlap_right: false,
        }
    }
}

fn parse_args() -> Args {
    let mut args = env::args().collect::<Vec<_>>();
    args.remove(0); // Remove program name

    if args.is_empty() {
        return Args::default();
    }

    let mut result = Args::default();
    let mut i = 0;

