                println!("{}", HELP_TEXT);
                process::exit(0);
            }
            "entropy" => {
                result.command = "entropy".to_string();
            }
            "tree" => {
                result.command = "tree".to_string();
            }
            "check" => {
                result.command = "check".to_string();
            }
