                if i + 1 < args.len() {
                    result.only.push(args[i + 1].clone());
                    i += 1;
                }
            }
            "--exclude" => {
                if i + 1 < args.len() {
                    result.exclude.push(args[i + 1].clone());
                    i += 1;
                }
            }
            "--unwrap-exports" => {
                result.unwrap_exports = true;
            }
            "--js-tsconfig-paths" => {
                result.js_tsconfig_paths = parse_bool(&args.get(i + 1).cloned().unwrap_or_else(|| "true".to_string()));
            }
            "--js-workspaces" => {
                result.js_workspaces = parse_bool(&args.get(i + 1).cloned().unwrap_or_else(|| "true".to_string()));
            }
            "--python-exclude-conditional-imports" => {
                result.python_exclude_conditional_imports = parse_bool(&args.get(i + 1).cloned().unwrap_or_else(|| "false".to_string()));
            }
            "--json" => {
                result.json = true;
            }
            "--enable-gui" => {
                result.enable_gui = true;
            }
            "--no-browser-open" => {
                result.no_browser_open = true;
            }
            "--render-path" => {
                if i + 1 < args.len() {
                    result.render_path = Some(PathBuf::from(&args[i + 1]));
                    i += 1;
                }
            }
            "-l" | "--overlap-left" => {
                result.overlap_left = true;
            }
            "-r" | "--overlap-right" => {
                result.overlap_right = true;
            }
            _ => {
                if !arg.starts_with('-') {
                    result.files.push(arg.clone());
                }
            }
        }
        i += 1;
    }

    result
}

fn parse_bool(s: &str) -> bool {
    matches!(s, "true" | "1" | "yes" | "on")
}

fn main() {
    let args = parse_args();

    match args.command.as_str() {
        "entropy" => entropy(&args),
        "tree" => tree(&args),
        "check" => check(&args),
        "explain" => explain(&args),
        "config" => config_cmd(&args),
        _ => {
            println!("{}", HELP_TEXT);
            process::exit(1);
        }
    }
}

