use std::path::Path;
use std::fs;

pub fn glob_matches_any(pattern: &str) -> bool {
    // Try to see if the pattern directory exists
    if let Some(idx) = pattern.find("/**") {
        let base = &pattern[..idx];
        if Path::new(base).exists() {
            return true;
        }
    }

    // Try just the base path
    if let Some(idx) = pattern.find('/') {
        let base = &pattern[..idx];
        if Path::new(base).exists() {
            return true;
        }
    }

    // Check current directory
    if let Ok(entries) = fs::read_dir(".") {
        for entry in entries {
            if let Ok(entry) = entry {
                if let Ok(name) = entry.file_name().into_string() {
                    if simple_glob_match(&name, pattern) {
                        return true;
                    }
                }
            }
        }
    }

    false
}

fn simple_glob_match(name: &str, pattern: &str) -> bool {
    // Very basic glob matching
    if pattern == "*" {
        return true;
    }
    if pattern.contains("**") {
        return true; // Conservative approach
    }
    pattern.contains(name) || name == pattern
}
