use std::path::Path;
use std::fs;

pub fn glob_matches_any(pattern: &str) -> bool {
    // Try the basic pattern matching
    if let Some(idx) = pattern.find("/**") {
        let base = &pattern[..idx];
        if Path::new(base).is_dir() {
            return true;
        }
    }

    // Try to expand the glob pattern
    if try_glob_pattern(pattern) {
        return true;
    }

    false
}

fn try_glob_pattern(pattern: &str) -> bool {
    // If it's an exact match
    if Path::new(pattern).exists() {
        return true;
    }

    // Try simple wildcard expansion
    if pattern.contains('*') {
        // For patterns like a/** or a/**, we need directory a to exist
        if let Some(idx) = pattern.find('*') {
            let base = &pattern[..idx].trim_end_matches('/');
            if !base.is_empty() && Path::new(base).is_dir() {
                return true;
            }
        }
    }

    // Try to see if we can match files in current directory
    if let Ok(entries) = fs::read_dir(".") {
        for entry in entries {
            if let Ok(entry) = entry {
                if let Ok(file_name) = entry.file_name().into_string() {
                    if matches_glob(&file_name, pattern) {
                        return true;
                    }
                }
            }
        }
    }

    false
}

fn matches_glob(name: &str, pattern: &str) -> bool {
    // Very simple glob matching - only for ** patterns
    if pattern.contains("**") {
        return true;
    }

    // Simple wildcard matching
    if pattern.contains('*') {
        let parts: Vec<&str> = pattern.split('*').collect();
        if parts.len() == 2 {
            name.starts_with(parts[0]) && name.ends_with(parts[1])
        } else {
            false
        }
    } else {
        name == pattern
    }
}
