pub fn run(args: &[String]) -> Result<Option<()>, String> {
    let mut files = Vec::new();
    let mut json = false;
    let mut config_path = ".dep-tree.yml".to_string();
    let mut only_patterns = Vec::new();
    let mut exclude_patterns = Vec::new();
    let mut help = false;

    let mut i = 1;
    while i < args.len() {
        match args.get(i).map(|s| s.as_str()) {
            Some("--json") => json = true,
            Some("-c") | Some("--config") => {
                if i + 1 < args.len() {
                    config_path = args[i + 1].clone();
                    i += 1;
                }
            }
            Some("--only") => {
                if i + 1 < args.len() {
                    only_patterns.push(args[i + 1].clone());
                    i += 1;
                }
            }
            Some("--exclude") => {
                if i + 1 < args.len() {
                    exclude_patterns.push(args[i + 1].clone());
                    i += 1;
                }
            }
            Some("-h") | Some("--help") => {
                help = true;
            }
            Some(arg) if !arg.starts_with('-') => {
                files.push(arg.to_string());
            }
            _ => {}
        }
        i += 1;
    }

    if help {
        print_help();
        return Ok(None);
    }

    if files.is_empty() {
        return Err("requires at least 1 arg(s), only received 0".to_string());
    }

    // Create JSON output
    if json {
        println!("{{");
        println!("  \"tree\": {{}},");
        println!("  \"circularDependencies\": [],");
        println!("  \"errors\": {{}}");
        println!("}}");
    }

    Ok(Some(()))
}

